<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;Auth::requireAdmin();if(!Auth::isSuperAdmin()){http_response_code(403);exit('Only the Super Admin can delete a complete draft workflow.');}$pdo=Database::connection();if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid security token.');}$eventId=(int)($_POST['event_id']??0);$dance=in_array((string)($_POST['dance_style']??''),['bachata','salsa'],true)?(string)$_POST['dance_style']:'bachata';$division=(string)($_POST['division']??'');$mode=in_array((string)($_POST['mode']??''),['manual','automated'],true)?(string)$_POST['mode']:'manual';$confirm=(string)($_POST['confirm']??'');try{$roundStmt=$pdo->prepare("SELECT r.id,r.status,r.round_type,e.name event_name,e.status event_status FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.event_id=:e AND r.dance_style=:dance AND r.division=:d ORDER BY r.id");$roundStmt->execute(['e'=>$eventId,'dance'=>$dance,'d'=>$division]);$rounds=$roundStmt->fetchAll();if(!$rounds)throw new RuntimeException('Draft scoring workflow not found.');if((string)$rounds[0]['event_status']==='published')throw new RuntimeException('Published events cannot be deleted here. Roll back the publication first.');$ids=array_map('intval',array_column($rounds,'id'));$ph=implode(',',array_fill(0,count($ids),'?'));$published=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_publications WHERE final_round_id IN ($ph) AND status='published'");$published->execute($ids);if((int)$published->fetchColumn()>0)throw new RuntimeException('This workflow is published. Roll it back before deleting it.');$counts=[];foreach(['competitors'=>'bdc_scoring_entries','judges'=>'bdc_scoring_judges','scores'=>'bdc_scoring_marks','calculated_results'=>'bdc_scoring_results','final_pairs'=>'bdc_scoring_final_pairs','final_scores'=>'bdc_scoring_final_marks','final_results'=>'bdc_scoring_final_results','judge_sessions'=>'bdc_scoring_judge_sessions'] as $label=>$table){$s=$pdo->prepare("SELECT COUNT(*) FROM {$table} WHERE round_id IN ($ph)");$s->execute($ids);$counts[$label]=(int)$s->fetchColumn();}$hasData=array_sum($counts)>0;if($confirm!=='DELETE'){?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delete Draft Scoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:760px"><div class="card shadow-sm border-danger"><div class="card-body p-4"><h1 class="h4 text-danger">Delete Draft Scoring?</h1><p><strong><?=e($rounds[0]['event_name'])?></strong> · <?=e(ucfirst($dance))?> · <?=e(ucwords(str_replace('_',' ',$division)))?></p><?php if($hasData):?><div class="alert alert-danger"><strong>This draft already contains scoring data.</strong> Deleting it permanently removes the draft competitors, judges, scores, pairings and calculated results. The event itself will not be deleted.</div><ul><?php foreach($counts as $label=>$count):if($count):?><li><?=e(ucwords(str_replace('_',' ',$label)))?>: <?=$count?></li><?php endif;endforeach;?></ul><?php else:?><div class="alert alert-warning">This draft is empty. The event itself will remain available for a new scoring workflow.</div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="dance_style" value="<?=e($dance)?>"><input type="hidden" name="division" value="<?=e($division)?>"><input type="hidden" name="mode" value="<?=e($mode)?>"><label class="form-label">Type <strong>DELETE</strong> to confirm</label><input class="form-control mb-3" name="confirm" autocomplete="off" required><div class="d-flex gap-2"><button class="btn btn-danger">Delete Draft Scoring</button><a class="btn btn-outline-secondary" href="index.php?mode=<?=e($mode)?>">Cancel</a></div></form></div></div></main></body></html><?php exit;}$pdo->beginTransaction();$publication=$pdo->prepare("SELECT id FROM bdc_scoring_publications WHERE final_round_id IN ($ph) AND status<>'published'");$publication->execute($ids);$publicationIds=array_map('intval',$publication->fetchAll(PDO::FETCH_COLUMN));if($publicationIds){$pubPh=implode(',',array_fill(0,count($publicationIds),'?'));$pdo->prepare("DELETE FROM bdc_scoring_publication_documents WHERE publication_id IN ($pubPh)")->execute($publicationIds);$pdo->prepare("DELETE FROM bdc_scoring_publication_points WHERE publication_id IN ($pubPh)")->execute($publicationIds);$pdo->prepare("DELETE FROM bdc_scoring_publications WHERE id IN ($pubPh)")->execute($publicationIds);}$pdo->prepare("DELETE FROM bdc_scoring_judge_sessions WHERE round_id IN ($ph)")->execute($ids);$pair=$pdo->prepare("SELECT id FROM bdc_scoring_final_pairs WHERE round_id IN ($ph)");$pair->execute($ids);$pairIds=array_map('intval',$pair->fetchAll(PDO::FETCH_COLUMN));if($pairIds){$pph=implode(',',array_fill(0,count($pairIds),'?'));$pdo->prepare("DELETE FROM bdc_scoring_final_results WHERE pair_id IN ($pph)")->execute($pairIds);$pdo->prepare("DELETE FROM bdc_scoring_final_marks WHERE pair_id IN ($pph)")->execute($pairIds);}foreach(['bdc_scoring_final_results','bdc_scoring_final_marks','bdc_scoring_final_pairs','bdc_scoring_results','bdc_scoring_marks','bdc_scoring_judges','bdc_scoring_entries','bdc_scoring_audit'] as $table){$s=$pdo->prepare("DELETE FROM {$table} WHERE round_id IN ($ph)");$s->execute($ids);}$pdo->prepare("DELETE FROM bdc_scoring_rounds WHERE id IN ($ph)")->execute($ids);$pdo->commit();header('Location: index.php?mode='.rawurlencode($mode).'&draft_deleted=1',true,303);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);echo '<!doctype html><html><body style="font-family:Arial;padding:30px"><h2>Delete blocked</h2><p>'.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'</p><p><a href="index.php?mode='.htmlspecialchars($mode,ENT_QUOTES,'UTF-8').'">Back to Scoring Dashboard</a></p></body></html>';exit;}